use std::time::Duration;
fn format_duration(d: Duration) -> String {
    // Guess how original formats: maybe they do something like:
    // let ms = d.as_millis(); etc.
    format!("{:?}", d)
}
fn main() {
    let tests = vec![
        Duration::from_micros(256) + Duration::from_nanos(516),
        Duration::from_millis(2) + Duration::from_micros(199) + Duration::from_nanos(385),
        Duration::from_millis(117) + Duration::from_micros(640) + Duration::from_nanos(261),
        Duration::from_secs(4) + Duration::from_millis(562) + Duration::from_micros(702) + Duration::from_nanos(816),
        Duration::from_nanos(282_757),
    ];
    for d in tests {
        println!("debug: {:?}", d);
        // Try custom formatting similar to observed: "Time elapsed: 2ms 199us 385ns"
        let total_nanos = d.as_nanos();
        let secs = total_nanos / 1_000_000_000;
        let rem = total_nanos % 1_000_000_000;
        let ms = rem / 1_000_000;
        let rem2 = rem % 1_000_000;
        let us = rem2 / 1000;
        let ns = rem2 % 1000;
        let mut parts = Vec::new();
        if secs>0 {
            parts.push(format!("{}s", secs));
        }
        if ms>0 || (secs>0 && (us>0 || ns>0)) {
            parts.push(format!("{}ms", ms));
        }
        if us>0 || (ms>0 && ns>0) || (secs>0 && ns>0) {
            parts.push(format!("{}us", us));
        }
        parts.push(format!("{}ns", ns));
        println!("custom: {}", parts.join(" "));
    }
}
