cat > src/main.rs <<'RS'
use clap::Parser;
use std::fs::File;
use std::io::{BufReader, BufRead, Read};
use std::path::PathBuf;
use std::sync::{Arc, atomic::{AtomicBool, Ordering}};
use std::time::Instant;

#[derive(Parser, Debug)]
#[command(name = "executable", about = "Find the password of protected ZIP files", version)]
struct Args {
    #[arg(short = 'i', long = "inputFile", value_name = "inputFile")]
    input_file: PathBuf,

    #[arg(short = 'w', long = "workers", value_name = "workers")]
    workers: Option<String>,

    #[arg(short = 'p', long = "passwordDictionary", value_name = "passwordDictionary")]
    password_dictionary: Option<PathBuf>,

    #[arg(short = 'c', long = "charset", value_name = "charset", default_value = "lud")]
    charset: String,

    #[arg(long = "charsetFile", value_name = "charsetFile")]
    charset_file: Option<PathBuf>,

    #[arg(long = "minPasswordLen", value_name = "minPasswordLen", default_value = "1")]
    min_password_len: Option<String>,

    #[arg(long = "maxPasswordLen", value_name = "maxPasswordLen", default_value = "10")]
    max_password_len: Option<String>,

    #[arg(long = "fileNumber", value_name = "fileNumber", default_value = "0")]
    file_number: Option<String>,

    #[arg(short = 's', long = "startingPassword", value_name = "startingPassword")]
    starting_password: Option<String>,
}

fn print_cli_error(msg: &str) {
    eprintln!("CLI argument error - {}", msg);
    std::process::exit(1);
}

fn parse_usize_positive(s: &str, name: &str) -> usize {
    // This is called after clap already validated digit? But we need to handle custom errors for positive.
    // For workers, min, max, fileNumber, clap will have already validated invalid digit.
    // However we need to check positive.
    match s.parse::<i64>() {
        Ok(v) => {
            if v <= 0 {
                if name == "workers" {
                    print_cli_error(&format!("'{}' must be positive", name));
                } else if name == "minPasswordLen" {
                    print_cli_error(&format!("'{}' must be positive", name));
                } else if name == "maxPasswordLen" {
                    print_cli_error(&format!("'{}' must be positive", name));
                } else {
                    print_cli_error(&format!("'{}' must be positive", name));
                }
            }
            v as usize
        },
        Err(_) => {
            // Should have been caught by clap, but fallback
            print_cli_error(&format!("'{}' must be positive", name));
            unreachable!()
        }
    }
}

fn main() {
    let args_raw = Args::parse();

    // Custom parsing for numbers because clap with Option<String> will not auto validate digit? Actually our fields are Option<String> to allow clap to show its own error for invalid digit.
