fn pow_usize(base: usize, exp: usize) -> usize {
    // Use u128 to avoid overflow, but return usize saturated? For large exp, may overflow; cap to usize::MAX
    let mut result: u128 = 1;
    for _ in 0..exp {
        result = result * base as u128;
        if result > usize::MAX as u128 {
            return usize::MAX;
        }
    }
    result as usize
}

fn index_to_password(mut idx: usize, len: usize, charset: &[char]) -> String {
    let base = charset.len();
    let mut chars = vec![' '; len];
    for i in (0..len).rev() {
        let pos = idx % base;
        chars[i] = charset[pos];
        idx /= base;
    }
    chars.into_iter().collect()
}

fn verify_zipcrypto_password(pwd: &[u8], enc_header: &[u8], check_byte: u8) -> bool {
    if enc_header.len() < 12 {
        return false;
    }
    // Initialize keys
    let mut key0: u32 = 305419896;
    let mut key1: u32 = 591751049;
    let mut key2: u32 = 878082192;

    // Build crctable
    let mut crctable = [0u32; 256];
    for i in 0..256 {
        let mut crc = i as u32;
        for _ in 0..8 {
            if crc & 1 != 0 {
                crc = (crc >> 1) ^ 0xEDB88320;
            } else {
                crc >>= 1;
            }
        }
        crctable[i] = crc;
    }

    let crc32 = |ch: u8, crc: u32| -> u32 {
        (crc >> 8) ^ crctable[((crc ^ ch as u32) & 0xFF) as usize]
    };

    let mut update_keys = |c: u8| {
        key0 = crc32(c, key0);
        key1 = key1.wrapping_add(key0 & 0xFF);
        key1 = key1.wrapping_mul(134775813).wrapping_add(1);
        key2 = crc32((key1 >> 24) as u8, key2);
    };

    for &b in pwd {
        update_keys(b);
    }

    // Decrypt header
    let mut plain = [0u8; 12];
    for i in 0..12 {
        let c = enc_header[i];
        let k = key2 | 2;
        let plain_byte = c ^ (((k * (k ^ 1) >> 8) & 0xFF) as u8);
        update_keys(plain_byte);
        plain[i] = plain_byte;
    }
    plain[11] == check_byte
}

fn verify_aes_password(pwd: &[u8], salt: &[u8], verify: &[u8], key_len: usize) -> bool {
    if salt.is_empty() || verify.len() != 2 {
        return false;
    }
    let dk_len = 2*key_len + 2;
    // Use pbkdf2
    let mut dk = vec![0u8; dk_len];
    pbkdf2::pbkdf2::<hmac::Hmac<sha1::Sha1>>(pwd, salt, 1000, &mut dk);
    &dk[dk_len-2..] == verify
}
