                    else:
                        return rest
                else:
                    if i+1 >= len(argv):
                        clap_error_required_value(long_name)
                    nxt = argv[i+1]
                    if nxt.startswith('-'):
                        # For -i, -w etc, -1 should be unexpected
                        # But for -p, -c, -s, maybe also unexpected? Let's check.
                        # For -c -1 we saw unexpected, for -p -1 unexpected, for -s -1 unexpected, for -i -1 unexpected
                        clap_error_unexpected_arg(nxt)
                    return nxt

            if opt_char == 'i':
                val = get_val(rest, '--inputFile <inputFile>')
                if rest == "":
                    i+=1
