        extra_end = extra_start + local_extra_len
        extra = zip_data[extra_start:extra_end]
        strength = 1
        p = 0
        while p+4 <= len(extra):
            id_ = int.from_bytes(extra[p:p+2], 'little')
            size = int.from_bytes(extra[p+2:p+4], 'little')
            p+=4
            if p+size > len(extra):
                break
            data = extra[p:p+size]
            if id_ == 0x9901 and len(data)>=6:
                strength = data[4]
            p+=size
        salt_len = {1:8,2:12,3:16}.get(strength,8)
        key_len = {1:16,2:24,3:32}.get(strength,16)
