    print("zip-password-finder 0.10.3")

def clap_error_invalid_value(val, opt):
    sys.stderr.write(f"error: invalid value '{val}' for '{opt}': invalid digit found in string\n")
    sys.stderr.write("\nFor more information, try '--help'.\n")
    sys.exit(2)

def clap_error_unexpected_arg(arg):
    sys.stderr.write(f"error: unexpected argument '{arg}' found\n")
    sys.stderr.write("\nUsage: executable [OPTIONS] --inputFile <inputFile>\n")
    sys.stderr.write("\nFor more information, try '--help'.\n")
    sys.exit(2)

def clap_error_required_value(opt):
    sys.stderr.write(f"error: a value is required for '{opt}' but none was supplied\n")
    sys.stderr.write("\nFor more information, try '--help'.\n")
    sys.exit(2)

def clap_error_missing_required():
    sys.stderr.write("error: the following required arguments were not provided:\n  --inputFile <inputFile>\n")
    sys.stderr.write("\nUsage: executable --inputFile <inputFile>\n")
    sys.stderr.write("\nFor more information, try '--help'.\n")
    sys.exit(2)

def cli_error(msg):
    sys.stderr.write(f"CLI argument error - \"{msg}\"\n")
    sys.exit(1)

# Argument parsing
def parse_args(argv):
    result = {
        'inputFile': None,
        'workers': None,
        'passwordDictionary': None,
        'charset': 'lud',
        'charsetFile': None,
        'minPasswordLen': '1',
        'maxPasswordLen': '10',
        'fileNumber': '0',
        'startingPassword': None,
    }
    i=1
    while i < len(argv):
        arg = argv[i]
        if arg == '-h' or arg == '--help':
            print_help()
            sys.exit(0)
        if arg == '-V' or arg == '--version':
            print_version()
            sys.exit(0)
        if arg.startswith('--'):
            if '=' in arg:
                opt, val = arg.split('=',1)
            else:
                opt = arg
                val = None

            if opt == '--inputFile':
                if val is None:
                    if i+1 >= len(argv):
                        clap_error_required_value('--inputFile <inputFile>')
                    nxt = argv[i+1]
                    if nxt.startswith('-') and len(nxt)>1:
                        clap_error_unexpected_arg(nxt)
                    val = nxt
                    i+=1
                result['inputFile'] = val
            elif opt == '--workers':
                if val is None:
                    if i+1 >= len(argv):
                        clap_error_required_value('--workers <workers>')
                    nxt = argv[i+1]
                    if nxt.startswith('-'):
                        clap_error_unexpected_arg(nxt)
                    val = nxt
                    i+=1
                if val.startswith('-'):
                    clap_error_invalid_value(val, '--workers <workers>')
                if not val.isdigit():
                    clap_error_invalid_value(val, '--workers <workers>')
                result['workers'] = val
            elif opt == '--passwordDictionary':
                if val is None:
                    if i+1 >= len(argv):
                        clap_error_required_value('--passwordDictionary <passwordDictionary>')
                    nxt = argv[i+1]
                    if nxt.startswith('-'):
                        clap_error_unexpected_arg(nxt)
                    val = nxt
                    i+=1
                result['passwordDictionary'] = val
            elif opt == '--charset':
                if val is None:
                    if i+1 >= len(argv):
                        clap_error_required_value('--charset <charset>')
                    nxt = argv[i+1]
                    if nxt.startswith('-'):
                        clap_error_unexpected_arg(nxt)
                    val = nxt
                    i+=1
                result['charset'] = val
            elif opt == '--charsetFile':
                if val is None:
                    if i+1 >= len(argv):
                        clap_error_required_value('--charsetFile <charsetFile>')
                    nxt = argv[i+1]
                    if nxt.startswith('-'):
                        clap_error_unexpected_arg(nxt)
                    val = nxt
                    i+=1
                result['charsetFile'] = val
            elif opt == '--minPasswordLen':
                if val is None:
                    if i+1 >= len(argv):
                        clap_error_required_value('--minPasswordLen <minPasswordLen>')
                    nxt = argv[i+1]
                    if nxt.startswith('-'):
                        clap_error_unexpected_arg(nxt)
                    val = nxt
                    i+=1
                if val.startswith('-'):
                    clap_error_invalid_value(val, '--minPasswordLen <minPasswordLen>')
                if not val.isdigit():
                    clap_error_invalid_value(val, '--minPasswordLen <minPasswordLen>')
                result['minPasswordLen'] = val
            elif opt == '--maxPasswordLen':
                if val is None:
                    if i+1 >= len(argv):
                        clap_error_required_value('--maxPasswordLen <maxPasswordLen>')
                    nxt = argv[i+1]
                    if nxt.startswith('-'):
                        clap_error_unexpected_arg(nxt)
                    val = nxt
                    i+=1
                if val.startswith('-'):
                    clap_error_invalid_value(val, '--maxPasswordLen <maxPasswordLen>')
                if not val.isdigit():
                    clap_error_invalid_value(val, '--maxPasswordLen <maxPasswordLen>')
                result['maxPasswordLen'] = val
            elif opt == '--fileNumber':
                if val is None:
                    if i+1 >= len(argv):
                        clap_error_required_value('--fileNumber <fileNumber>')
                    nxt = argv[i+1]
                    if nxt.startswith('-'):
                        clap_error_unexpected_arg(nxt)
                    val = nxt
                    i+=1
                if val.startswith('-'):
                    clap_error_invalid_value(val, '--fileNumber <fileNumber>')
                if not val.isdigit():
                    clap_error_invalid_value(val, '--fileNumber <fileNumber>')
                result['fileNumber'] = val
            elif opt == '--startingPassword':
                if val is None:
                    if i+1 >= len(argv):
                        clap_error_required_value('--startingPassword <startingPassword>')
                    nxt = argv[i+1]
                    if nxt.startswith('-') and len(nxt)>1:
                        # Check if nxt looks like an option? For startingPassword, -1 is considered unexpected, but "-" alone maybe password?
                        # We'll treat any starting with '-' as unexpected, as observed for -1
                        clap_error_unexpected_arg(nxt)
                    val = nxt
                    i+=1
                result['startingPassword'] = val
            else:
                clap_error_unexpected_arg(arg)
        elif arg.startswith('-') and len(arg)>1:
            # short
            opt_char = arg[1]
            rest = arg[2:]

            if opt_char == 'h':
                print_help()
                sys.exit(0)
            if opt_char == 'V':
                print_version()
                sys.exit(0)

            def get_val(rest, long_name):
                if rest != "":
                    if rest.startswith('='):
                        return rest[1:]
                    else:
                        return rest
                else:
                    if i+1 >= len(argv):
                        clap_error_required_value(long_name)
                    nxt = argv[i+1]
                    if nxt.startswith('-'):
                        # For -i, -w etc, -1 should be unexpected
                        # But for -p, -c, -s, maybe also unexpected? Let's check.
                        # For -c -1 we saw unexpected, for -p -1 unexpected, for -s -1 unexpected, for -i -1 unexpected
                        clap_error_unexpected_arg(nxt)
                    return nxt

            if opt_char == 'i':
                val = get_val(rest, '--inputFile <inputFile>')
                if rest == "":
                    i+=1
                result['inputFile'] = val
            elif opt_char == 'w':
                val = get_val(rest, '--workers <workers>')
                if rest == "":
                    i+=1
                # handle attached -1
                if val.startswith('-'):
                    if rest != "":
                        clap_error_invalid_value(val, '--workers <workers>')
                    else:
                        clap_error_unexpected_arg(val)
                if not val.isdigit():
                    clap_error_invalid_value(val, '--workers <workers>')
                result['workers'] = val
            elif opt_char == 'p':
                val = get_val(rest, '--passwordDictionary <passwordDictionary>')
                if rest == "":
                    i+=1
                result['passwordDictionary'] = val
            elif opt_char == 'c':
                val = get_val(rest, '--charset <charset>')
                if rest == "":
                    i+=1
                result['charset'] = val
            elif opt_char == 's':
                val = get_val(rest, '--startingPassword <startingPassword>')
                if rest == "":
                    i+=1
                result['startingPassword'] = val
            else:
                clap_error_unexpected_arg(arg)
        else:
            clap_error_unexpected_arg(arg)
        i+=1

    if result['inputFile'] is None:
        clap_error_missing_required()
    return result

def pow_usize(base, exp):
    # returns Python int, may be huge
    return pow(base, exp)

def index_to_password(idx, length, charset):
    base = len(charset)
    chars = [''] * length
    for pos in range(length-1, -1, -1):
        chars[pos] = charset[idx % base]
        idx //= base
    return ''.join(chars)

def password_to_index(pwd, charset):
    base = len(charset)
    idx = 0
    for c in pwd:
        try:
            pos = charset.index(c)
        except ValueError:
            return None
        idx = idx * base + pos
    return idx

def main():
    args = parse_args(sys.argv)

    # validations
    if not os.path.exists(args['inputFile']):
        sys.stderr.write("CLI argument error - \"'inputFile' does not exist\"\n")
        sys.exit(1)

    if args['passwordDictionary'] is not None and not os.path.exists(args['passwordDictionary']):
        sys.stderr.write("CLI argument error - \"'passwordDictionary' does not exist\"\n")
        sys.exit(1)

    if args['charsetFile'] is not None and not os.path.exists(args['charsetFile']):
        sys.stderr.write("CLI argument error - \"'charsetFile' does not exist\"\n")
        sys.exit(1)

    try:
        min_len = int(args['minPasswordLen'])
    except:
        min_len = 1
    try:
        max_len = int(args['maxPasswordLen'])
    except:
        max_len = 10

    if min_len <=0:
        sys.stderr.write("CLI argument error - \"'minPasswordLen' must be positive\"\n")
        sys.exit(1)
    if max_len <=0:
        sys.stderr.write("CLI argument error - \"'maxPasswordLen' must be positive\"\n")
        sys.exit(1)
    if max_len < min_len:
        sys.stderr.write("CLI argument error - \"'maxPasswordLen' must be equal or greater than 'minPasswordLen'\"\n")
        sys.exit(1)

    workers = 0
    if args['workers'] is not None:
        try:
            workers = int(args['workers'])
        except:
            workers = 0
        if workers <=0:
            sys.stderr.write("CLI argument error - \"'workers' must be positive\"\n")
            sys.exit(1)
    else:
        import multiprocessing
        try:
            workers = multiprocessing.cpu_count()
        except:
            workers = 4
        if workers <=0:
            workers = 4

    try:
        file_number = int(args['fileNumber'])
    except:
        file_number = 0

    if args['startingPassword'] is not None and args['passwordDictionary'] is not None:
        sys.stderr.write("CLI argument error - \"'startingPassword' cannot be used with a dictionary file\"\n")
        sys.exit(1)

    if args['startingPassword'] is not None:
        sp_len = len(args['startingPassword'])
        if sp_len < min_len or sp_len > max_len:
            sys.stderr.write("CLI argument error - \"'startingPassword' does not respect 'max_password_len' or 'min_password_len' configuration\"\n")
            sys.exit(1)

    # charset
    charset_chars = []
    if args['charsetFile'] is not None:
        with open(args['charsetFile'], 'rb') as f:
            content = f.read()
        s = content.decode('utf-8', errors='replace')
        chars = []
        for c in s:
            if c == '\n':
                continue
            chars.append(c)
        # sorted unique
        chars = sorted(set(chars))
        charset_chars = chars
    else:
        charset_opt = args['charset']
        expanded = []
        for ch in charset_opt:
            if ch == 'l':
                expanded.extend([chr(ord('a')+i) for i in range(26)])
            elif ch == 'u':
                expanded.extend([chr(ord('A')+i) for i in range(26)])
            elif ch == 'd':
                expanded.extend([chr(ord('0')+i) for i in range(10)])
            elif ch == 'h':
                expanded.extend([chr(ord('0')+i) for i in range(10)])
                expanded.extend([chr(ord('a')+i) for i in range(6)])
            elif ch == 'H':
                expanded.extend([chr(ord('0')+i) for i in range(10)])
                expanded.extend([chr(ord('A')+i) for i in range(6)])
            elif ch == 's':
                s_chars = " !\"#$%&'()*+,-./:;<=>?@[\\]^_`{|}~"
                expanded.extend(list(s_chars))
            else:
                sys.stderr.write(f"CLI argument error - \"Unknown charset option '{ch}'\"\n")
                sys.exit(1)
        expanded = sorted(set(expanded))
        charset_chars = expanded

    if args['startingPassword'] is not None:
        sp = args['startingPassword']
        for c in sp:
            if c not in charset_chars:
                sys.stderr.write("CLI argument error - \"'startingPassword' uses characters out of the generation charset\"\n")
                sys.exit(1)

    # zip parsing
    zip_path = args['inputFile']
    try:
        with open(zip_path, 'rb') as f:
            zip_data = f.read()
    except:
        sys.stderr.write("Invalid zip file error - invalid Zip archive: Could not find EOCD\n")
        sys.exit(1)

    # find EOCD
    eocd_pos = None
    search_start = max(0, len(zip_data)-65557)
    for i in range(len(zip_data)-4, search_start-1, -1):
        if zip_data[i:i+4] == b'\x50\x4b\x05\x06':
            eocd_pos = i
            break
    if eocd_pos is None:
        sys.stderr.write("Invalid zip file error - invalid Zip archive: Could not find EOCD\n")
        sys.exit(1)
    if eocd_pos+22 > len(zip_data):
        sys.stderr.write("Invalid zip file error - invalid Zip archive: Could not find EOCD\n")
        sys.exit(1)
    cd_num_entries = int.from_bytes(zip_data[eocd_pos+10:eocd_pos+12], 'little')
    cd_offset = int.from_bytes(zip_data[eocd_pos+16:eocd_pos+20], 'little')

    class CentralEntry:
        def __init__(self, flag, comp_method, crc, comp_size, local_offset, file_name):
            self.flag = flag
            self.comp_method = comp_method
            self.crc = crc
            self.comp_size = comp_size
            self.local_offset = local_offset
            self.file_name = file_name

    entries = []
    pos = cd_offset
    for _ in range(cd_num_entries):
        if pos+46 > len(zip_data):
            break
        if zip_data[pos:pos+4] != b'\x50\x4b\x01\x02':
            break
        flag = int.from_bytes(zip_data[pos+8:pos+10], 'little')
        comp_method = int.from_bytes(zip_data[pos+10:pos+12], 'little')
        crc = int.from_bytes(zip_data[pos+16:pos+20], 'little')
        comp_size = int.from_bytes(zip_data[pos+20:pos+24], 'little')
        fname_len = int.from_bytes(zip_data[pos+28:pos+30], 'little')
        extra_len = int.from_bytes(zip_data[pos+30:pos+32], 'little')
        comment_len = int.from_bytes(zip_data[pos+32:pos+34], 'little')
        local_offset = int.from_bytes(zip_data[pos+42:pos+46], 'little')
        fname_start = pos+46
        fname_end = fname_start+fname_len
        if fname_end > len(zip_data):
            break
        file_name = zip_data[fname_start:fname_end].decode('utf-8', errors='replace')
        entries.append(CentralEntry(flag, comp_method, crc, comp_size, local_offset, file_name))
        pos = fname_end + extra_len + comment_len

    if file_number >= len(entries):
        sys.stderr.write(f"File number not found within archive error - '{file_number}'\n")
        sys.exit(1)

    entry = entries[file_number]

    if entry.flag & 1 == 0:
        sys.stderr.write(f"Invalid zip file error - the selected file in the archive is not encrypted (file_number:{file_number} file_name:{entry.file_name})\n")
        sys.exit(1)

    is_aes = entry.comp_method == 99

    local_offset = entry.local_offset
    if local_offset+30 > len(zip_data):
        sys.stderr.write("Invalid zip file error - invalid Zip archive: Could not find EOCD\n")
        sys.exit(1)
    if zip_data[local_offset:local_offset+4] != b'\x50\x4b\x03\x04':
        sys.stderr.write("Invalid zip file error - invalid Zip archive: Could not find EOCD\n")
        sys.exit(1)
    local_comp_size = int.from_bytes(zip_data[local_offset+18:local_offset+22], 'little')
    local_fname_len = int.from_bytes(zip_data[local_offset+26:local_offset+28], 'little')
    local_extra_len = int.from_bytes(zip_data[local_offset+28:local_offset+30], 'little')
    local_header_end = local_offset+30+local_fname_len+local_extra_len
    if local_header_end+local_comp_size > len(zip_data):
        sys.stderr.write("Invalid zip file error - invalid Zip archive: Could not find EOCD\n")
        sys.exit(1)
    enc_data = zip_data[local_header_end:local_header_end+local_comp_size]

    aes_salt = b''
    aes_verify = b''
    aes_key_len = 0
    zipcrypto_header = b''
    zipcrypto_check = 0

    if is_aes:
        extra_start = local_offset+30+local_fname_len
        extra_end = extra_start + local_extra_len
        extra = zip_data[extra_start:extra_end]
        strength = 1
        p = 0
        while p+4 <= len(extra):
            id_ = int.from_bytes(extra[p:p+2], 'little')
            size = int.from_bytes(extra[p+2:p+4], 'little')
            p+=4
            if p+size > len(extra):
                break
            data = extra[p:p+size]
            if id_ == 0x9901 and len(data)>=6:
                strength = data[4]
            p+=size
        salt_len = {1:8,2:12,3:16}.get(strength,8)
        key_len = {1:16,2:24,3:32}.get(strength,16)
        if len(enc_data) < salt_len+2+10:
            sys.stderr.write(f"Invalid zip file error - the selected file in the archive is not encrypted (file_number:{file_number} file_name:{entry.file_name})\n")
            sys.exit(1)
        aes_salt = enc_data[0:salt_len]
        aes_verify = enc_data[salt_len:salt_len+2]
        aes_key_len = key_len
    else:
        if len(enc_data) < 12:
            sys.stderr.write(f"Invalid zip file error - the selected file in the archive is not encrypted (file_number:{file_number} file_name:{entry.file_name})\n")
            sys.exit(1)
        zipcrypto_header = enc_data[0:12]
        # time for check
        pos2 = cd_offset
        target_time = 0
        for i in range(cd_num_entries):
            if pos2+46 > len(zip_data):
                break
            time_tmp = int.from_bytes(zip_data[pos2+12:pos2+14], 'little')
            fname_len_tmp = int.from_bytes(zip_data[pos2+28:pos2+30], 'little')
            extra_len_tmp = int.from_bytes(zip_data[pos2+30:pos2+32], 'little')
            comment_len_tmp = int.from_bytes(zip_data[pos2+32:pos2+34], 'little')
            if i == file_number:
                target_time = time_tmp
                break
            pos2 += 46 + fname_len_tmp + extra_len_tmp + comment_len_tmp
        if entry.flag & 8 != 0:
            zipcrypto_check = (target_time >> 8) & 0xFF
        else:
            zipcrypto_check = (entry.crc >> 24) & 0xFF

    start_time_ns = time.time_ns()

    found_password = None

    if len(charset_chars)==0 and args['passwordDictionary'] is None:
        # simulate panic
        def panic_worker(wid):
            sys.stderr.write(f"\nthread 'worker-{wid}' ({threading.get_ident()}) panicked at src/password_gen.rs:60:46:\ncharset non empty\n")
            sys.stderr.write("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n")
        threads=[]
        for wid in range(1, workers+1):
            t = threading.Thread(target=panic_worker, args=(wid,))
            t.start()
            threads.append(t)
        for t in threads:
            t.join()
        elapsed_ns = time.time_ns() - start_time_ns
        secs = elapsed_ns // 1_000_000_000
        rem = elapsed_ns % 1_000_000_000
        ms = rem // 1_000_000
        rem2 = rem % 1_000_000
        us = rem2 // 1000
        ns = rem2 % 1000
        parts=[]
        if secs>0:
            parts.append(f"{secs}s"); parts.append(f"{ms}ms"); parts.append(f"{us}us"); parts.append(f"{ns}ns")
        elif ms>0:
            parts.append(f"{ms}ms"); parts.append(f"{us}us"); parts.append(f"{ns}ns")
        elif us>0:
            parts.append(f"{us}us"); parts.append(f"{ns}ns")
        else:
            parts.append(f"{ns}ns")
        print(f"Time elapsed: {' '.join(parts)}")
        print("Password not found")
        sys.exit(0)

    # verify functions
    # precompute crctable for zipcrypto
    crctable = []
    for i in range(256):
        crc = i
        for _ in range(8):
            if crc & 1:
                crc = (crc >> 1) ^ 0xEDB88320
            else:
                crc >>= 1
        crctable.append(crc)

    def verify_zipcrypto(pwd_bytes, header, check):
        if len(header)<12:
            return False
        key0 = 305419896
        key1 = 591751049
        key2 = 878082192
        def crc32(ch, crc):
            return (crc >> 8) ^ crctable[(crc ^ ch) & 0xFF]
        def update_keys(c):
            nonlocal key0, key1, key2
            key0 = crc32(c, key0)
            key1 = (key1 + (key0 & 0xFF)) & 0xFFFFFFFF
            key1 = (key1 * 134775813 + 1) & 0xFFFFFFFF
            key2 = crc32((key1 >> 24) & 0xFF, key2)
        for b in pwd_bytes:
            update_keys(b)
        plain = bytearray()
        for c in header:
            k = key2 | 2
            pb = c ^ ((k * (k ^ 1) >> 8) & 0xFF)
            update_keys(pb)
            plain.append(pb)
        return plain[11] == check

    def verify_aes(pwd_bytes, salt, verify, key_len):
        if not salt or len(verify)!=2:
            return False
        dk_len = 2*key_len+2
        dk = hashlib.pbkdf2_hmac('sha1', pwd_bytes, salt, 1000, dklen=dk_len)
        return dk[-2:] == verify

    if args['passwordDictionary'] is not None:
        # dictionary
        dict_path = args['passwordDictionary']
        with open(dict_path, 'rb') as f:
            content = f.read()
        text = content.decode('utf-8', errors='replace')
        # Rust lines() behavior: split on \n, strip trailing \r, and no trailing empty for final newline?
        # We'll implement: split on \n, then for each part, if it ends with \r, strip \r.
        # Then, if original text ends with \n, we should not include an extra empty after? Actually split on \n for text ending with \n gives trailing "".
        # Rust lines() would not produce an extra empty for trailing \n, but would produce empty for consecutive \n\n?
        # Let's implement: parts = text.split('\n')
        # If text ends with '\n', then last part is "" from split, but lines() would discard it if it's the trailing empty? Actually "a\n".split('\n') => ["a",""], lines() => ["a"]. So we should pop last if text ends with '\n'.
        # But "a\n\n" split => ["a","",""], lines() => ["a",""] (one empty). So we should pop only one trailing empty if text ends with '\n'.
        parts = text.split('\n')
        if text.endswith('\n'):
            # Remove last element which is "" due to trailing newline
            if parts and parts[-1] == "":
                parts = parts[:-1]
        # Now for each part, strip trailing \r
        passwords = []
        for p in parts:
            if p.endswith('\r'):
                p = p[:-1]
            passwords.append(p)

        found_flag = threading.Event()
        found_result = [None]
        lock = threading.Lock()

        def worker(start_idx, end_idx):
            for idx in range(start_idx, end_idx):
                if found_flag.is_set():
                    break
                pwd = passwords[idx]
                pwd_bytes = pwd.encode('utf-8')
                ok = False
                if is_aes:
                    ok = verify_aes(pwd_bytes, aes_salt, aes_verify, aes_key_len)
                else:
                    ok = verify_zipcrypto(pwd_bytes, zipcrypto_header, zipcrypto_check)
                if ok:
                    with lock:
                        if found_result[0] is None:
