            elif opt == '--startingPassword':
                if val is None:
                    if i+1 >= len(argv):
                        clap_error_required_value('--startingPassword <startingPassword>')
                    nxt = argv[i+1]
                    if nxt.startswith('-') and len(nxt)>1:
                        clap_error_unexpected_arg(nxt)
                    val = nxt
                    i+=1
                result['startingPassword'] = val
            else:
                clap_error_unexpected_arg(arg)
        elif arg.startswith('-') and len(arg)>1:
            opt_char = arg[1]
            rest = arg[2:]
            if opt_char == 'h':
                print_help()
                sys.exit(0)
            if opt_char == 'V':
                print_version()
                sys.exit(0)
            def get_val(rest, long_name):
                if rest != "":
                    if rest.startswith('='):
                        return rest[1:]
                    else:
                        return rest
                else:
                    if i+1 >= len(argv):
                        clap_error_required_value(long_name)
                    nxt = argv[i+1]
                    if nxt.startswith('-'):
                        clap_error_unexpected_arg(nxt)
                    return nxt
            if opt_char == 'i':
                val = get_val(rest, '--inputFile <inputFile>')
                if rest == "":
                    i+=1
                result['inputFile'] = val
            elif opt_char == 'w':
                val = get_val(rest, '--workers <workers>')
                if rest == "":
                    i+=1
                if val.startswith('-'):
                    if rest != "":
                        clap_error_invalid_value(val, '--workers <workers>')
                    else:
                        clap_error_unexpected_arg(val)
                if not val.isdigit():
                    clap_error_invalid_value(val, '--workers <workers>')
                result['workers'] = val
            elif opt_char == 'p':
                val = get_val(rest, '--passwordDictionary <passwordDictionary>')
                if rest == "":
